import sys

MOD = 998244353

def main():
    data = list(map(int, sys.stdin.buffer.read().split()))
    if not data:
        return
    n = data[0]
    a = data[1:]
    v = max(a)

    spf = list(range(v + 1))
    for i in range(2, int(v ** 0.5) + 1):
        if spf[i] == i:
            for j in range(i * i, v + 1, i):
                if spf[j] == j:
                    spf[j] = i

    phi = list(range(v + 1))
    for i in range(2, v + 1):
        if phi[i] == i:
            for j in range(i, v + 1, i):
                phi[j] -= phi[j] // i

    weighted_count = [0] * (v + 1)

    def divisors(x):
        result = [1]
        while x > 1:
            p = spf[x]
            exponent = 0
            while x % p == 0:
                x //= p
                exponent += 1
            old = result[:]
            power = 1
            for _ in range(exponent):
                power *= p
                result.extend(y * power for y in old)
        return result

    answer = 0
    weight = 1
    output = []
    for i, x in enumerate(a):
        ds = divisors(x)
        if i:
            gcd_sum = sum(phi[d] * weighted_count[d] for d in ds) % MOD
            answer = (2 * answer + gcd_sum) % MOD
        output.append(str(answer))
        for d in ds:
            weighted_count[d] = (weighted_count[d] + weight) % MOD
        weight = weight * 2 % MOD

    sys.stdout.write('\n'.join(output))

if __name__ == '__main__':
    main()

