import sys

def solve(data):
    it = iter(map(int, data.split()))
    n = next(it); m = next(it); q = next(it)
    edges = [(next(it)-1, next(it)-1, next(it)) for _ in range(m)]
    queries = []
    closed = [False] * m
    for _ in range(q):
        t = next(it)
        if t == 1:
            x = next(it) - 1
            queries.append((1, x))
            closed[x] = True
        else:
            queries.append((2, next(it)-1, next(it)-1))

    INF = 10**30
    d = [[INF] * n for _ in range(n)]
    for i in range(n):
        d[i][i] = 0
    for idx, (u, v, w) in enumerate(edges):
        if not closed[idx]:
            d[u][v] = d[v][u] = w

    for k in range(n):
        dk = d[k]
        for i in range(n):
            dik = d[i][k]
            di = d[i]
            for j in range(i, n):
                z = dik + dk[j]
                if z < di[j]:
                    di[j] = z
                    d[j][i] = z

    answers = []
    for query in reversed(queries):
        if query[0] == 2:
            value = d[query[1]][query[2]]
            answers.append(str(-1 if value == INF else value))
        else:
            u, v, w = edges[query[1]]
            if w >= d[u][v]:
                continue
            du, dv = d[u], d[v]
            for i in range(n):
                diu, div = d[i][u], d[i][v]
                di = d[i]
                for j in range(i, n):
                    value = diu + w + dv[j]
                    other = div + w + du[j]
                    if other < value:
                        value = other
                    if value < di[j]:
                        di[j] = value
                        d[j][i] = value

    return '\n'.join(reversed(answers))

