class Solution:
    def countKReducibleNumbers(self, s: str, k: int) -> int:
        MOD = 10**9 + 7
        n = len(s)
        comb = [[0] * (n + 1) for _ in range(n + 1)]
        comb[0][0] = 1
        for i in range(1, n + 1):
            comb[i][0] = comb[i][i] = 1
            for j in range(1, i):
                comb[i][j] = (comb[i - 1][j - 1] + comb[i - 1][j]) % MOD

        good = [False] * (n + 1)
        for c in range(1, n + 1):
            value = c
            steps = 0
            while value != 1 and steps <= k:
                value = value.bit_count()
                steps += 1
            good[c] = value == 1 and steps <= k - 1

        answer = 0
        ones = 0
        for i, bit in enumerate(s):
            if bit == '1':
                remaining = n - i - 1
                for suffix_ones in range(remaining + 1):
                    if good[ones + suffix_ones]:
                        answer = (answer + comb[remaining][suffix_ones]) % MOD
                ones += 1
        return answer

