import sys, heapq

def solve():
    input = sys.stdin.readline
    n = int(input())
    g = [input().strip() for _ in range(n)]
    inf = 10**9
    dist = [[inf] * n for _ in range(n)]
    heap = []
    for i in range(n):
        dist[i][i] = 0
        heapq.heappush(heap, (0, i, i))

    incoming = [[[] for _ in range(26)] for _ in range(n)]
    outgoing = [[[] for _ in range(26)] for _ in range(n)]
    for i in range(n):
        for j, ch in enumerate(g[i]):
            if ch != '-':
                c = ord(ch) - ord('a')
                outgoing[i][c].append(j)
                incoming[j][c].append(i)
                if dist[i][j] > 1:
                    dist[i][j] = 1
                    heapq.heappush(heap, (1, i, j))

    while heap:
        d, x, y = heapq.heappop(heap)
        if d != dist[x][y]:
            continue
        nd = d + 2
        for c in range(26):
            left = incoming[x][c]
            right = outgoing[y][c]
            for a in left:
                row = dist[a]
                for b in right:
                    if nd < row[b]:
                        row[b] = nd
                        heapq.heappush(heap, (nd, a, b))

    for row in dist:
        print(*(-1 if x == inf else x for x in row))

solve()

