import sys

def mountain(x):
    # x is a positive crease index
    b = x & -x
    return 1 if (x & (b << 1)) == 0 else 0

def main():
    data=list(map(int,sys.stdin.buffer.read().split()))
    if not data:return
    n=data[0]; a=data[1:]
    lim=(1<<100)-a[-1]-1
    # The low part is where all changes caused by the given displacements occur.
    # Enumerate it directly; supplement with the useful dyadic boundary points.
    K=min(lim, 1<<22)
    best=0
    for i in range(1,K+1):
        s=0
        for d in a:
            s += mountain(i+d)
        if s>best: best=s
    cand=set()
    for k in range(0,101):
        q=1<<k
        for d in a:
            for z in (q-d,q-d-1,q-d+1,q//2-d,q+q//2-d):
                if 1<=z<=lim: cand.add(z)
        for z in (q-2,q-1,q,q+1,q+2):
            if 1<=z<=lim:cand.add(z)
    for i in cand:
        s=sum(mountain(i+d) for d in a)
        if s>best:best=s
    print(best)
main()

