import sys

def solve():
    data = list(map(int, sys.stdin.buffer.read().split()))
    if not data:
        return
    n, m = data[0], data[1]
    A = data[2:2 + n]
    B = data[2 + n:2 + 2 * n]

    # With two colors, a good sequence is forced by its first element,
    # and no move can change it while preserving goodness.
    if m == 2:
        print(0 if A == B else -1)
        return

    # k[i] describes the lift of B[i] reached from the lift of A[i].
    # The sign of every adjacent lifted difference is invariant.
    k = 0
    lifted_displacements = [B[0] - A[0]]
    for i in range(1, n):
        bd = B[i] - B[i - 1]
        if A[i] > A[i - 1]:
            if bd < 0:
                k += 1
        else:
            if bd > 0:
                k -= 1
        lifted_displacements.append(B[i] + k * m - A[i])

    # A common lift by c*m is still possible.  Minimize the L1 sum over c;
    # an optimum is attained at one of the integers adjacent to -median/m.
    lifted_displacements.sort()
    median = lifted_displacements[n // 2]
    q = (-median) // m
    answer = min(
        sum(abs(x + (q + t) * m) for x in lifted_displacements)
        for t in (-1, 0, 1)
    )
    print(answer)

if __name__ == "__main__":
    solve()

