class Solution:
    def permute(self, n: int, k: int) -> List[int]:
        cap = 10**15 + 1
        fact = [1] * (n + 1)
        for i in range(1, n + 1):
            fact[i] = min(cap, fact[i - 1] * i)

        def ways(odd: int, even: int, last: int) -> int:
            length = odd + even
            if length == 0:
                return 1
            first = 1 - last
            required_odd = (length + 1) // 2 if first else length // 2
            if odd != required_odd or even != length - required_odd:
                return 0
            return min(cap, fact[odd] * fact[even])

        unused = list(range(1, n + 1))
        result = []
        previous = None

        for _ in range(n):
            chosen = None
            total_odd = sum(value & 1 for value in unused)
            for value in unused:
                parity = value & 1
                if previous is not None and parity == previous:
                    continue
                remaining_odd = total_odd - parity
                remaining_even = len(unused) - 1 - remaining_odd
                count = ways(remaining_odd, remaining_even, parity)
                if count < k:
                    k -= count
                else:
                    chosen = value
                    break
            if chosen is None:
                return []
            result.append(chosen)
            unused.remove(chosen)
            previous = chosen & 1

        return result

