class Solution:
 def countNonDecreasingSubarrays(self, nums: List[int], k: int) -> int:
  n=len(nums); ps=[0]
  for x in nums: ps.append(ps[-1]+x)
  ng=[-1]*n; st=[]
  for i,x in enumerate(nums):
   while st and nums[st[-1]]<x: ng[st.pop()]=i
   st.append(i)
  LOG=n.bit_length(); up=[ng]
  for p in range(1,LOG):
   prev=up[-1]; up.append([-1 if j<0 else prev[j] for j in prev])
  def cost(l,r):
   c=l; s=0
   for p in range(LOG-1,-1,-1):
    j=up[p][c]
    if j!=-1 and j<=r:
     s+=nums[c]*(j-c); c=j
   s+=nums[c]*(r-c+1)
   return s-(ps[r+1]-ps[l])
  ans=0
  for r in range(n):
   lo,hi=0,r
   while lo<hi:
    m=(lo+hi)//2
    if cost(m,r)<=k: hi=m
    else: lo=m+1
   ans+=r-lo+1
  return ans

