from array import array

class Solution:
    def maximumSubarrayXor(self, nums, queries):
        n = len(nums)
        score = [array('I', [0]) * n for _ in range(n)]
        best = [array('I', [0]) * n for _ in range(n)]

        for i, x in enumerate(nums):
            score[i][i] = x
            best[i][i] = x

        for length_minus_one in range(1, n):
            for left in range(n - length_minus_one):
                right = left + length_minus_one
                value = score[left + 1][right] ^ score[left][right - 1]
                score[left][right] = value
                maximum = value
                if best[left + 1][right] > maximum:
                    maximum = best[left + 1][right]
                if best[left][right - 1] > maximum:
                    maximum = best[left][right - 1]
                best[left][right] = maximum

        return [best[left][right] for left, right in queries]

