def even_scores(a):
    res = [0] * (len(a) + 1)
    low, high = [], []
    slow = shigh = 0
    for cnt, x in enumerate(a, 1):
        if low and x <= -low[0]:
            heappush(low, -x); slow += x
        else:
            heappush(high, x); shigh += x
        target = cnt // 2
        while len(low) > target:
            y = -heappop(low); slow -= y
            heappush(high, y); shigh += y
        while len(low) < target:
            y = heappop(high); shigh -= y
            heappush(low, -y); slow += y
        if cnt % 2 == 0:
            res[cnt] = shigh - slow
    return res

