class Solution:
    def shortestMatchingSubstring(self, s: str, p: str) -> int:
        n = len(s)
        x = p.find('*')
        y = p.find('*', x + 1)
        parts = [p[:x], p[x + 1:y], p[y + 1:]]

        def occurrences(t):
            m = len(t)
            found = [False] * (n + 1)
            if m == 0:
                return found
            pi = [0] * m
            for i in range(1, m):
                j = pi[i - 1]
                while j and t[i] != t[j]:
                    j = pi[j - 1]
                if t[i] == t[j]:
                    j += 1
                pi[i] = j
            j = 0
            for i, ch in enumerate(s):
                while j and ch != t[j]:
                    j = pi[j - 1]
                if ch == t[j]:
                    j += 1
                if j == m:
                    found[i - m + 1] = True
                    j = pi[j - 1]
            return found

        found = [occurrences(t) for t in parts]
        next_at = []
        for t, flags in zip(parts, found):
            if not t:
                next_at.append(None)
                continue
            nxt = [n + 1] * (n + 2)
            current = n + 1
            for i in range(n, -1, -1):
                if flags[i]:
                    current = i
                nxt[i] = current
            next_at.append(nxt)

        a, b, c = parts
        la, lb, lc = map(len, parts)
        best = n + 1
        if a:
            starts = (i for i in range(n - la + 1) if found[0][i])
        else:
            starts = range(n + 1)
        for start in starts:
            pos = start + la
            if b:
                pos = next_at[1][pos]
            if pos > n:
                continue
            pos += lb
            if c:
                pos = next_at[2][pos]
            if pos > n:
                continue
            best = min(best, pos + lc - start)
        return -1 if best == n + 1 else best

