def solve():
    a = list(map(int, sys.stdin.buffer.read().split()))
    if not a:
        return
    n, W = a[0], a[1]
    dp = [0] + [-10**30] * W
    p = 2
    for _ in range(n):
        w, v = a[p], a[p + 1]
        p += 2
        old = dp
        nd = [-10**30] * (W + 1)
        for r in range(min(w, W + 1)):
            h = []
            ptr = 0
            for y in range((W - r) // w + 1):
                z = old[r + y * w]
                if z > -10**29:
                    m, b = y, z - y * y
                    while len(h) >= 2:
                        m1, b1 = h[-2]
                        m2, b2 = h[-1]
                        if (b1 - b2) * (m - m2) >= (b2 - b) * (m2 - m1):
                            h.pop()
                        else:
                            break
                    h.append((m, b))
                    if ptr >= len(h):
                        ptr = len(h) - 1
                x = 2 * y - v
                while ptr + 1 < len(h) and h[ptr + 1][0] * x + h[ptr + 1][1] >= h[ptr][0] * x + h[ptr][1]:
                    ptr += 1
                if h:
                    m, b = h[ptr]
                    nd[r + y * w] = -y * y + y * v + m * x + b
        dp = nd
    print(max(dp))

