import sys
from collections import deque

def solve():
    it = iter(map(int, sys.stdin.buffer.read().split()))
    try:
        n = next(it)
    except StopIteration:
        return
    m = next(it)
    graph = [[] for _ in range(n + 1)]
    incoming_to_one = []
    for _ in range(m):
        a = next(it)
        b = next(it)
        graph[a].append(b)
        if b == 1:
            incoming_to_one.append(a)

    distance = [-1] * (n + 1)
    distance[1] = 0
    queue = deque([1])
    while queue:
        v = queue.popleft()
        for to in graph[v]:
            if distance[to] == -1:
                distance[to] = distance[v] + 1
                queue.append(to)

    answer = min(
        (distance[v] + 1 for v in incoming_to_one if distance[v] != -1),
        default=-1,
    )
    print(answer)

if __name__ == "__main__":
    solve()

