class Solution:
    def getLargestOutlier(self, nums: List[int]) -> int:
        total = sum(nums)
        count = {}
        for v in nums:
            count[v] = count.get(v, 0) + 1
        for x in sorted(nums, reverse=True):
            rem = total - x
            if rem % 2:
                continue
            y = rem // 2
            available = count.get(y, 0) - (1 if y == x else 0)
            if available > 0:
                return x
        return 0

