import heapq

class Solution:
    def minOperations(self, n: int, m: int) -> int:
        if n == m:
            if n >= 2:
                for p in range(2, int(n ** 0.5) + 1):
                    if n % p == 0:
                        break
                else:
                    return -1
            return n

        digits = len(str(n))
        limit = 10 ** digits
        prime = bytearray(b'\x01') * limit
        prime[0] = 0
        prime[1] = 0
        for p in range(2, int((limit - 1) ** 0.5) + 1):
            if prime[p]:
                prime[p * p:limit:p] = b'\x00' * (((limit - 1 - p * p) // p) + 1)

        if prime[n] or prime[m]:
            return -1

        inf = 10 ** 30
        dist = [inf] * limit
        dist[n] = n
        heap = [(n, n)]
        places = [10 ** i for i in range(digits)]

        while heap:
            cost, value = heapq.heappop(heap)
            if cost != dist[value]:
                continue
            if value == m:
                return cost
            for place in places:
                digit = (value // place) % 10
                if digit < 9:
                    nxt = value + place
                    if not prime[nxt] and cost + nxt < dist[nxt]:
                        dist[nxt] = cost + nxt
                        heapq.heappush(heap, (cost + nxt, nxt))
                if digit > 0:
                    nxt = value - place
                    if not prime[nxt] and cost + nxt < dist[nxt]:
                        dist[nxt] = cost + nxt
                        heapq.heappush(heap, (cost + nxt, nxt))
        return -1

