from typing import List

class Solution:
    def beautifulSplits(self, nums: List[int]) -> int:
        n = len(nums)
        if n < 3:
            return 0
        sa = list(range(n))
        rank = list(nums)
        step = 1
        while step < n:
            sa.sort(key=lambda x: (rank[x], rank[x + step] if x + step < n else -1))
            new = [0] * n
            cls = 0
            for q in range(1, n):
                x, y = sa[q-1], sa[q]
                px = (rank[x], rank[x+step] if x+step < n else -1)
                py = (rank[y], rank[y+step] if y+step < n else -1)
                if px != py:
                    cls += 1
                new[y] = cls
            rank = new
            if cls == n - 1:
                break
            step <<= 1

        pos = [0] * n
        for q, x in enumerate(sa):
            pos[x] = q
        lcp = [0] * n
        h = 0
        for i in range(n):
            p = pos[i]
            if p:
                j = sa[p-1]
                while i+h < n and j+h < n and nums[i+h] == nums[j+h]:
                    h += 1
                lcp[p] = h
                if h:
                    h -= 1

        logs = [0] * (n+1)
        for x in range(2, n+1):
            logs[x] = logs[x//2] + 1
        table = [lcp]
        width = 1
        while (width << 1) <= n:
            old = table[-1]
            table.append([min(old[x], old[x+width])
                          for x in range(len(old)-width)])
            width <<= 1

        def has_lcp(i, j, need):
            x, y = pos[i], pos[j]
            if x > y:
                x, y = y, x
            length = y - x
            k = logs[length]
            row = table[k]
            return min(row[x+1], row[y-(1 << k)+1]) >= need

        ans = 0
        for i in range(1, n-1):
            first = has_lcp(0, i, i)
            if first:
                ans += max(0, n - 2*i)
            for d in range(1, n-i):
                if (not first or d < i) and has_lcp(i, i+d, d):
                    ans += 1
        return ans

