        def zfunc(a):
            m = len(a); z = [0]*m
            l = r = 0
            for k in range(1,m):
                if k < r:
                    z[k] = min(r-k, z[k-l])
                while k+z[k] < m and a[z[k]] == a[k+z[k]]:
                    z[k] += 1
                if k+z[k] > r:
                    l, r = k, k+z[k]
            return z
