class Solution:
    def minMaxWeight(self, n: int, edges: List[List[int]], threshold: int) -> int:
        reverse = [[] for _ in range(n)]
        for a, b, w in edges:
            reverse[b].append((a, w))

        weights = sorted({w for _, _, w in edges})

        def reachable(limit: int) -> bool:
            seen = [False] * n
            seen[0] = True
            queue = deque([0])
            count = 1
            while queue:
                v = queue.popleft()
                for u, w in reverse[v]:
                    if w <= limit and not seen[u]:
                        seen[u] = True
                        count += 1
                        queue.append(u)
            return count == n

        if not weights or not reachable(weights[-1]):
            return -1
        left, right = 0, len(weights) - 1
        while left < right:
            mid = (left + right) // 2
            if reachable(weights[mid]):
                right = mid
            else:
                left = mid + 1
        return weights[left]

