class Solution:
    def maxActiveSectionsAfterTrade(self, s: str) -> int:
        n = len(s)
        base = s.count('1')
        zero_lengths = []
        internal_lengths = []
        merged_gains = []
        i = 0
        while i < n:
            j = i
            while j < n and s[j] == s[i]:
                j += 1
            if s[i] == '0':
                zero_lengths.append(j - i)
            elif i > 0 and j < n:
                internal_lengths.append(j - i)
                a = i - 1
                while a >= 0 and s[a] == '0':
                    a -= 1
                b = j
                while b < n and s[b] == '0':
                    b += 1
                merged_gains.append((i - a - 1) + (b - j))
            i = j
        if not internal_lengths:
            return base
        gain = max(merged_gains + [max(zero_lengths) - min(internal_lengths)])
        return base + gain

